// Deployment transport only. The frozen preview server and generated bytes stay unchanged.
import {readFile,lstat} from 'node:fs/promises';
import {join} from 'node:path';
import {createHash} from 'node:crypto';
import {AppError} from '../shared/contracts.ts';
const sha=(b:string|Buffer)=>createHash('sha256').update(b).digest('hex');
export function presentationPath(path:string){const match=/^\/(preview|harness|builds)\/([a-f0-9]{64})(?:\/(index\.html|app\.js|app\.css))?$/.exec(path);if(!match||((match[1]==='builds')!==Boolean(match[3])))throw new AppError('PREVIEW_PATH','无效的版本化预览路径',404);return {role:match[1],version:match[2],asset:match[3]};}
export function generatedCsp(base:string){return `sandbox allow-scripts; default-src 'none'; script-src ${base}/app.js; style-src ${base}/app.css; connect-src 'none'; img-src 'none'; font-src 'none'; frame-src 'none'; worker-src 'none'; form-action 'none'; object-src 'none'; base-uri 'none'; frame-ancestors 'self'`;}
export async function adaptPreviewCsp(input:{path:string;origin:string;backendHost:string;dataRoot:string;configSha256:string;status:number;headers:Record<string,string>;bytes:Buffer}){
  if(!input.origin.startsWith('https://'))return input.headers;
  const {version,asset}=presentationPath(input.path);if(input.status!==200||!asset)return input.headers;
  const directory=join(input.dataRoot,'artifacts',version),manifestFile=join(directory,'build-manifest.json');
  for(const p of [join(input.dataRoot,'artifacts'),directory,manifestFile]){const stat=await lstat(p);if(stat.isSymbolicLink()||p===manifestFile&&(!stat.isFile()||stat.size>131072))throw new AppError('PREVIEW_IDENTITY','预览产物类型无效',503);}
  const manifest=JSON.parse(await readFile(manifestFile,'utf8'));
  if(manifest.versionId!==version||manifest.configurationSha256!==input.configSha256||![manifest.sourceSha256,manifest.buildSha256,manifest.configurationSha256].every(x=>/^[a-f0-9]{64}$/.test(x))||sha(`${manifest.sourceSha256}:${manifest.buildSha256}:${manifest.configurationSha256}`)!==version||Object.keys(manifest.assets).some(k=>!['index.html','app.js','app.css'].includes(k))||!manifest.assets[asset]||manifest.assets[asset].sha256!==sha(input.bytes)||manifest.assets[asset].bytes!==input.bytes.length||input.headers['x-m0-5-source-sha256']!==manifest.sourceSha256||input.headers['x-m0-5-build-sha256']!==manifest.buildSha256)throw new AppError('PREVIEW_IDENTITY','预览响应与固定版本不匹配',503);
  const old=generatedCsp(`http://${input.backendHost}/builds/${version}`);
  if(input.headers['content-security-policy']!==old)throw new AppError('PREVIEW_CSP','上游 CSP 偏离冻结契约，已拒绝映射',503);
  return {...input.headers,'content-security-policy':generatedCsp(`${input.origin}/builds/${version}`)};
}
